import { useState, useRef } from 'react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { 
  Download, 
  Upload, 
  FileSpreadsheet, 
  FileText, 
  AlertCircle,
  CheckCircle
} from 'lucide-react';
import { useToast } from '../hooks/use-toast';
import * as XLSX from 'xlsx';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';
import { 
  getInitiatives, 
  getAwardPoints, 
  addInitiative, 
  addAwardPoint,
  db 
} from '../lib/database';

function ImportExportDialog({ open, onOpenChange, onSuccess }) {
  const { toast } = useToast();
  const [loading, setLoading] = useState(false);
  const [importResults, setImportResults] = useState(null);
  const fileInputRef = useRef(null);

  const handleExportInitiatives = async (format) => {
    setLoading(true);
    try {
      const initiatives = await getInitiatives();
      
      const exportData = initiatives.map((initiative, index) => ({
        'الرقم': index + 1,
        'اسم المبادرة': initiative.name,
        'الإدارة': initiative.department,
        'الحالة': initiative.status,
        'نسبة الإكمال (%)': initiative.completion_percentage,
        'الميزانية المخططة (درهم)': initiative.planned_budget || 0,
        'الميزانية المستخدمة (درهم)': initiative.used_budget || 0,
        'المسؤول': initiative.responsible_person,
        'تاريخ الإنشاء': new Date(initiative.created_at).toLocaleDateString('ar-AE'),
        'تاريخ التحديث': new Date(initiative.updated_at).toLocaleDateString('ar-AE')
      }));

      if (format === 'excel') {
        const ws = XLSX.utils.json_to_sheet(exportData);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, 'المبادرات');
        
        // Set column widths
        const colWidths = [
          { wch: 8 },  // الرقم
          { wch: 30 }, // اسم المبادرة
          { wch: 20 }, // الإدارة
          { wch: 15 }, // الحالة
          { wch: 15 }, // نسبة الإكمال
          { wch: 20 }, // الميزانية المخططة
          { wch: 20 }, // الميزانية المستخدمة
          { wch: 20 }, // المسؤول
          { wch: 15 }, // تاريخ الإنشاء
          { wch: 15 }  // تاريخ التحديث
        ];
        ws['!cols'] = colWidths;
        
        XLSX.writeFile(wb, `المبادرات_${new Date().toISOString().split('T')[0]}.xlsx`);
      } else if (format === 'csv') {
        const csv = XLSX.utils.sheet_to_csv(XLSX.utils.json_to_sheet(exportData));
        const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = `المبادرات_${new Date().toISOString().split('T')[0]}.csv`;
        link.click();
      }

      toast({
        title: "تم التصدير بنجاح",
        description: `تم تصدير ${initiatives.length} مبادرة إلى ملف ${format.toUpperCase()}`,
      });
    } catch (error) {
      console.error('Export error:', error);
      toast({
        title: "خطأ في التصدير",
        description: "حدث خطأ أثناء تصدير البيانات",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleExportAwardPoints = async (format) => {
    setLoading(true);
    try {
      const awardPoints = await getAwardPoints();
      
      const exportData = awardPoints.map((point, index) => ({
        'الرقم': index + 1,
        'نوع النقطة': point.point_type,
        'المعيار': point.standard,
        'تصنيف المعيار': point.standard_classification,
        'الإدارة': point.department,
        'الوصف': point.description,
        'الحالة': point.status,
        'المسؤول': point.responsible_person,
        'تاريخ الإنشاء': new Date(point.created_at).toLocaleDateString('ar-AE'),
        'تاريخ التحديث': new Date(point.updated_at).toLocaleDateString('ar-AE')
      }));

      if (format === 'excel') {
        const ws = XLSX.utils.json_to_sheet(exportData);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, 'نقاط الجائزة');
        
        // Set column widths
        const colWidths = [
          { wch: 8 },  // الرقم
          { wch: 15 }, // نوع النقطة
          { wch: 20 }, // المعيار
          { wch: 25 }, // تصنيف المعيار
          { wch: 20 }, // الإدارة
          { wch: 50 }, // الوصف
          { wch: 15 }, // الحالة
          { wch: 20 }, // المسؤول
          { wch: 15 }, // تاريخ الإنشاء
          { wch: 15 }  // تاريخ التحديث
        ];
        ws['!cols'] = colWidths;
        
        XLSX.writeFile(wb, `نقاط_الجائزة_${new Date().toISOString().split('T')[0]}.xlsx`);
      } else if (format === 'csv') {
        const csv = XLSX.utils.sheet_to_csv(XLSX.utils.json_to_sheet(exportData));
        const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = `نقاط_الجائزة_${new Date().toISOString().split('T')[0]}.csv`;
        link.click();
      }

      toast({
        title: "تم التصدير بنجاح",
        description: `تم تصدير ${awardPoints.length} نقطة جائزة إلى ملف ${format.toUpperCase()}`,
      });
    } catch (error) {
      console.error('Export error:', error);
      toast({
        title: "خطأ في التصدير",
        description: "حدث خطأ أثناء تصدير البيانات",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleExportPDF = async () => {
    setLoading(true);
    try {
      // Create a temporary div with dashboard content
      const tempDiv = document.createElement('div');
      tempDiv.style.position = 'absolute';
      tempDiv.style.left = '-9999px';
      tempDiv.style.width = '1200px';
      tempDiv.style.backgroundColor = 'white';
      tempDiv.style.padding = '20px';
      tempDiv.style.fontFamily = 'Arial, sans-serif';
      tempDiv.style.direction = 'rtl';

      const [initiatives, awardPoints] = await Promise.all([
        getInitiatives(),
        getAwardPoints()
      ]);

      tempDiv.innerHTML = `
        <div style="text-align: center; margin-bottom: 30px;">
          <h1 style="color: #ea580c; font-size: 24px; margin-bottom: 10px;">نظام التميز المؤسسي</h1>
          <h2 style="color: #4a4a4a; font-size: 18px;">هيئة الشارقة للإذاعة والتلفزيون</h2>
          <p style="color: #666; font-size: 14px;">تقرير شامل - ${new Date().toLocaleDateString('ar-AE')}</p>
        </div>

        <div style="margin-bottom: 30px;">
          <h3 style="color: #ea580c; font-size: 18px; margin-bottom: 15px; border-bottom: 2px solid #ea580c; padding-bottom: 5px;">ملخص المبادرات</h3>
          <div style="display: grid; grid-template-columns: repeat(4, 1fr); gap: 15px; margin-bottom: 20px;">
            <div style="background: #f8f9fa; padding: 15px; border-radius: 8px; text-align: center;">
              <div style="font-size: 24px; font-weight: bold; color: #ea580c;">${initiatives.length}</div>
              <div style="font-size: 12px; color: #666;">إجمالي المبادرات</div>
            </div>
            <div style="background: #f8f9fa; padding: 15px; border-radius: 8px; text-align: center;">
              <div style="font-size: 24px; font-weight: bold; color: #16a34a;">${initiatives.filter(i => i.status === 'مكتملة').length}</div>
              <div style="font-size: 12px; color: #666;">المبادرات المكتملة</div>
            </div>
            <div style="background: #f8f9fa; padding: 15px; border-radius: 8px; text-align: center;">
              <div style="font-size: 24px; font-weight: bold; color: #eab308;">${initiatives.filter(i => i.status === 'قيد التنفيذ').length}</div>
              <div style="font-size: 12px; color: #666;">قيد التنفيذ</div>
            </div>
            <div style="background: #f8f9fa; padding: 15px; border-radius: 8px; text-align: center;">
              <div style="font-size: 24px; font-weight: bold; color: #dc2626;">${initiatives.filter(i => i.status === 'متأخرة').length}</div>
              <div style="font-size: 12px; color: #666;">المتأخرة</div>
            </div>
          </div>
        </div>

        <div style="margin-bottom: 30px;">
          <h3 style="color: #ea580c; font-size: 18px; margin-bottom: 15px; border-bottom: 2px solid #ea580c; padding-bottom: 5px;">ملخص نقاط الجائزة</h3>
          <div style="display: grid; grid-template-columns: repeat(3, 1fr); gap: 15px; margin-bottom: 20px;">
            <div style="background: #f8f9fa; padding: 15px; border-radius: 8px; text-align: center;">
              <div style="font-size: 24px; font-weight: bold; color: #16a34a;">${awardPoints.filter(p => p.point_type === 'نقطة قوة').length}</div>
              <div style="font-size: 12px; color: #666;">نقاط القوة</div>
            </div>
            <div style="background: #f8f9fa; padding: 15px; border-radius: 8px; text-align: center;">
              <div style="font-size: 24px; font-weight: bold; color: #eab308;">${awardPoints.filter(p => p.point_type === 'نقطة تحسين').length}</div>
              <div style="font-size: 12px; color: #666;">نقاط التحسين</div>
            </div>
            <div style="background: #f8f9fa; padding: 15px; border-radius: 8px; text-align: center;">
              <div style="font-size: 24px; font-weight: bold; color: #ea580c;">${awardPoints.length}</div>
              <div style="font-size: 12px; color: #666;">إجمالي النقاط</div>
            </div>
          </div>
        </div>
      `;

      document.body.appendChild(tempDiv);

      const canvas = await html2canvas(tempDiv, {
        backgroundColor: 'white',
        scale: 2,
        useCORS: true
      });

      document.body.removeChild(tempDiv);

      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      
      const imgWidth = 190;
      const pageHeight = 297;
      const imgHeight = (canvas.height * imgWidth) / canvas.width;
      let heightLeft = imgHeight;
      let position = 10;

      pdf.addImage(imgData, 'PNG', 10, position, imgWidth, imgHeight);
      heightLeft -= pageHeight;

      while (heightLeft >= 0) {
        position = heightLeft - imgHeight;
        pdf.addPage();
        pdf.addImage(imgData, 'PNG', 10, position, imgWidth, imgHeight);
        heightLeft -= pageHeight;
      }

      pdf.save(`تقرير_نظام_التميز_${new Date().toISOString().split('T')[0]}.pdf`);

      toast({
        title: "تم التصدير بنجاح",
        description: "تم إنشاء تقرير PDF بنجاح",
      });
    } catch (error) {
      console.error('PDF export error:', error);
      toast({
        title: "خطأ في التصدير",
        description: "حدث خطأ أثناء إنشاء ملف PDF",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleFileImport = async (event) => {
    const file = event.target.files[0];
    if (!file) return;

    setLoading(true);
    setImportResults(null);

    try {
      const data = await file.arrayBuffer();
      const workbook = XLSX.read(data);
      const sheetName = workbook.SheetNames[0];
      const worksheet = workbook.Sheets[sheetName];
      const jsonData = XLSX.utils.sheet_to_json(worksheet);

      let successCount = 0;
      let errorCount = 0;
      const errors = [];

      // Determine if it's initiatives or award points based on columns
      const firstRow = jsonData[0];
      const isInitiatives = firstRow && ('اسم المبادرة' in firstRow || 'name' in firstRow);
      const isAwardPoints = firstRow && ('نوع النقطة' in firstRow || 'point_type' in firstRow);

      if (isInitiatives) {
        for (const [index, row] of jsonData.entries()) {
          try {
            const initiative = {
              name: row['اسم المبادرة'] || row['name'] || '',
              department: row['الإدارة'] || row['department'] || '',
              status: row['الحالة'] || row['status'] || 'لم تبدأ',
              completion_percentage: parseInt(row['نسبة الإكمال (%)'] || row['completion_percentage'] || 0),
              planned_budget: parseFloat(row['الميزانية المخططة (درهم)'] || row['planned_budget'] || 0),
              used_budget: parseFloat(row['الميزانية المستخدمة (درهم)'] || row['used_budget'] || 0),
              responsible_person: row['المسؤول'] || row['responsible_person'] || ''
            };

            if (!initiative.name || !initiative.department || !initiative.responsible_person) {
              throw new Error('البيانات المطلوبة مفقودة');
            }

            await addInitiative(initiative);
            successCount++;
          } catch (error) {
            errorCount++;
            errors.push(`الصف ${index + 2}: ${error.message}`);
          }
        }
      } else if (isAwardPoints) {
        for (const [index, row] of jsonData.entries()) {
          try {
            const awardPoint = {
              point_type: row['نوع النقطة'] || row['point_type'] || 'نقطة قوة',
              standard: row['المعيار'] || row['standard'] || '',
              standard_classification: row['تصنيف المعيار'] || row['standard_classification'] || '',
              department: row['الإدارة'] || row['department'] || '',
              description: row['الوصف'] || row['description'] || '',
              status: row['الحالة'] || row['status'] || 'لم تبدأ',
              responsible_person: row['المسؤول'] || row['responsible_person'] || ''
            };

            if (!awardPoint.standard || !awardPoint.department || !awardPoint.description || !awardPoint.responsible_person) {
              throw new Error('البيانات المطلوبة مفقودة');
            }

            await addAwardPoint(awardPoint);
            successCount++;
          } catch (error) {
            errorCount++;
            errors.push(`الصف ${index + 2}: ${error.message}`);
          }
        }
      } else {
        throw new Error('تنسيق الملف غير مدعوم. يجب أن يحتوي على أعمدة المبادرات أو نقاط الجائزة');
      }

      setImportResults({
        success: successCount,
        errors: errorCount,
        errorDetails: errors,
        type: isInitiatives ? 'المبادرات' : 'نقاط الجائزة'
      });

      if (successCount > 0) {
        onSuccess();
        toast({
          title: "تم الاستيراد بنجاح",
          description: `تم استيراد ${successCount} عنصر بنجاح`,
        });
      }

      if (errorCount > 0) {
        toast({
          title: "تحذير",
          description: `فشل في استيراد ${errorCount} عنصر`,
          variant: "destructive",
        });
      }
    } catch (error) {
      console.error('Import error:', error);
      toast({
        title: "خطأ في الاستيراد",
        description: error.message || "حدث خطأ أثناء استيراد البيانات",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    }
  };

  const handleBackupExport = async () => {
    setLoading(true);
    try {
      const [initiatives, awardPoints] = await Promise.all([
        getInitiatives(),
        getAwardPoints()
      ]);

      const backup = {
        version: '1.0',
        timestamp: new Date().toISOString(),
        data: {
          initiatives,
          awardPoints
        }
      };

      const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `نسخة_احتياطية_${new Date().toISOString().split('T')[0]}.json`;
      link.click();

      toast({
        title: "تم إنشاء النسخة الاحتياطية",
        description: "تم حفظ جميع البيانات في ملف النسخة الاحتياطية",
      });
    } catch (error) {
      console.error('Backup error:', error);
      toast({
        title: "خطأ في النسخة الاحتياطية",
        description: "حدث خطأ أثناء إنشاء النسخة الاحتياطية",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[700px] max-h-[90vh] overflow-y-auto" dir="rtl">
        <DialogHeader>
          <DialogTitle className="text-orange-600">استيراد وتصدير البيانات</DialogTitle>
          <DialogDescription>
            يمكنك تصدير البيانات إلى ملفات Excel أو CSV أو PDF، أو استيراد البيانات من ملفات Excel
          </DialogDescription>
        </DialogHeader>

        <Tabs defaultValue="export" className="w-full">
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="export">تصدير البيانات</TabsTrigger>
            <TabsTrigger value="import">استيراد البيانات</TabsTrigger>
          </TabsList>

          <TabsContent value="export" className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {/* Export Initiatives */}
              <Card>
                <CardHeader>
                  <CardTitle className="text-sm flex items-center gap-2">
                    <FileSpreadsheet className="h-4 w-4" />
                    تصدير المبادرات
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-2">
                  <Button
                    onClick={() => handleExportInitiatives('excel')}
                    disabled={loading}
                    className="w-full bg-green-600 hover:bg-green-700 text-white"
                    size="sm"
                  >
                    <Download className="h-4 w-4 ml-2" />
                    Excel
                  </Button>
                  <Button
                    onClick={() => handleExportInitiatives('csv')}
                    disabled={loading}
                    variant="outline"
                    className="w-full"
                    size="sm"
                  >
                    <Download className="h-4 w-4 ml-2" />
                    CSV
                  </Button>
                </CardContent>
              </Card>

              {/* Export Award Points */}
              <Card>
                <CardHeader>
                  <CardTitle className="text-sm flex items-center gap-2">
                    <FileSpreadsheet className="h-4 w-4" />
                    تصدير نقاط الجائزة
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-2">
                  <Button
                    onClick={() => handleExportAwardPoints('excel')}
                    disabled={loading}
                    className="w-full bg-green-600 hover:bg-green-700 text-white"
                    size="sm"
                  >
                    <Download className="h-4 w-4 ml-2" />
                    Excel
                  </Button>
                  <Button
                    onClick={() => handleExportAwardPoints('csv')}
                    disabled={loading}
                    variant="outline"
                    className="w-full"
                    size="sm"
                  >
                    <Download className="h-4 w-4 ml-2" />
                    CSV
                  </Button>
                </CardContent>
              </Card>

              {/* Export PDF Report */}
              <Card>
                <CardHeader>
                  <CardTitle className="text-sm flex items-center gap-2">
                    <FileText className="h-4 w-4" />
                    تقرير شامل
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <Button
                    onClick={handleExportPDF}
                    disabled={loading}
                    className="w-full bg-red-600 hover:bg-red-700 text-white"
                    size="sm"
                  >
                    <Download className="h-4 w-4 ml-2" />
                    PDF
                  </Button>
                </CardContent>
              </Card>

              {/* Backup */}
              <Card>
                <CardHeader>
                  <CardTitle className="text-sm flex items-center gap-2">
                    <Download className="h-4 w-4" />
                    نسخة احتياطية
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <Button
                    onClick={handleBackupExport}
                    disabled={loading}
                    variant="outline"
                    className="w-full"
                    size="sm"
                  >
                    <Download className="h-4 w-4 ml-2" />
                    JSON
                  </Button>
                </CardContent>
              </Card>
            </div>
          </TabsContent>

          <TabsContent value="import" className="space-y-4">
            <Card>
              <CardHeader>
                <CardTitle className="text-sm flex items-center gap-2">
                  <Upload className="h-4 w-4" />
                  استيراد من ملف Excel أو CSV
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div>
                  <Label htmlFor="file-upload">اختر ملف Excel أو CSV</Label>
                  <Input
                    id="file-upload"
                    type="file"
                    ref={fileInputRef}
                    accept=".xlsx,.xls,.csv"
                    onChange={handleFileImport}
                    disabled={loading}
                    className="mt-2"
                  />
                  <p className="text-xs text-gray-500 mt-1">
                    يجب أن يحتوي الملف على الأعمدة المطلوبة للمبادرات أو نقاط الجائزة
                  </p>
                </div>

                {importResults && (
                  <div className="border rounded-lg p-4 bg-gray-50">
                    <h4 className="font-medium mb-2 flex items-center gap-2">
                      <CheckCircle className="h-4 w-4 text-green-600" />
                      نتائج الاستيراد - {importResults.type}
                    </h4>
                    <div className="space-y-2 text-sm">
                      <div className="text-green-600">
                        ✓ تم استيراد {importResults.success} عنصر بنجاح
                      </div>
                      {importResults.errors > 0 && (
                        <div className="text-red-600">
                          ✗ فشل في استيراد {importResults.errors} عنصر
                        </div>
                      )}
                      {importResults.errorDetails.length > 0 && (
                        <details className="mt-2">
                          <summary className="cursor-pointer text-red-600 font-medium">
                            عرض تفاصيل الأخطاء
                          </summary>
                          <div className="mt-2 space-y-1 text-xs">
                            {importResults.errorDetails.map((error, index) => (
                              <div key={index} className="text-red-600">
                                {error}
                              </div>
                            ))}
                          </div>
                        </details>
                      )}
                    </div>
                  </div>
                )}

                <div className="bg-blue-50 border border-blue-200 rounded-lg p-3">
                  <div className="flex items-start gap-2">
                    <AlertCircle className="h-4 w-4 text-blue-600 mt-0.5" />
                    <div className="text-sm text-blue-800">
                      <p className="font-medium mb-1">متطلبات الملف:</p>
                      <ul className="text-xs space-y-1">
                        <li>• للمبادرات: اسم المبادرة، الإدارة، المسؤول (مطلوبة)</li>
                        <li>• لنقاط الجائزة: المعيار، الإدارة، الوصف، المسؤول (مطلوبة)</li>
                        <li>• يمكن استخدام الأسماء العربية أو الإنجليزية للأعمدة</li>
                      </ul>
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>

        <DialogFooter>
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={loading}
          >
            إغلاق
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

export default ImportExportDialog;
